	 * Loads a PFX / PKCS#12 container from the file path in ARG1. ARG2 follows the password contract below. The same contract is used by LoadPfxBytes, LoadPfxBd, and LoadPfxEncoded; it does not apply to LoadPem. The password argument has two modes: Plain password: For any non-JSON value P, Chilkat uses P for both integrity verification and all private-key bags. skipPrivateKeys is _FALSE_. JSON options: After trimming leading and trailing whitespace, JSON mode is used only when the value begins with {, ends with }, and parses as valid JSON. All three recognized members are optional and case-sensitive. {   "integrity": "integrity-password",   "privKeys": "private-key-password",   "skipPrivateKeys": false }MemberAccepted valueDefault when omitted integrityStringIntegrity verification is skipped. privKeysStringThe empty string is used as the password for every private-key bag. skipPrivateKeysJSON Boolean true, or a string equal to true without regard to case_FALSE_ Unknown JSON members are silently ignored. A misspelled member such as privkeys therefore does not produce a JSON error; the documented default is used instead. The single privKeys password applies to every private-key bag. Per-bag passwords are not supported. Certificate-only loading: When skipPrivateKeys is true, private-key bags are not processed and the privKeys password is irrelevant. Integrity verification is still performed when an integrity member is supplied. Empty versus omitted integrity password: A plain empty string requests integrity verification using an empty password. To intentionally skip integrity verification, use JSON and omit integrity, for example {"skipPrivateKeys":true} or {}. Literal-password collision: A real password that, after trimming, is a valid JSON object text is interpreted as options, and there is no force-literal escape. Text enclosed in braces that is not valid JSON falls back to literal-password handling. Independent protection roles: PKCS#12 can use one password for the container integrity MAC and another for encrypted private-key bags. A correct integrity password does not validate the privKeys password. If integrity verification succeeds but private-key decryption fails, the load still fails unless private keys were skipped. Destructive replacement: This method always replaces the current contents. The object is cleared before opening and importing the file, so any failure—including a missing file, invalid password, or malformed PFX—leaves the Pfx object empty. Load into a new object when the previously loaded contents must be preserved on failure.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#LoadPfxFile
	 * @param ?string $path
	 * @param ?string $password
	 * @return bool
	 */
	function LoadPfxFile($path,$password) {
		return CkPfx_LoadPfxFile($this->_cPtr,$path,$password);
	}

	/**
	 * Copies the private key at the zero-based index ARG1 into ARG2. The first private key is at index 0; valid indexes are less than NumPrivateKeys.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#PrivateKeyAt
	 * @param int $index
	 * @param CkPrivateKey $privKey
	 * @return bool
	 */
	function PrivateKeyAt($index,$privKey) {
		return CkPfx_PrivateKeyAt($this->_cPtr,$index,$privKey);
	}

	/**
	 * Sets a safe-bag attribute on a private key or certificate contained in this PFX. A safe-bag attribute is metadata attached to an item inside a PKCS#12/PFX container; it does not change the certificate or private-key material itself.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#SetSafeBagAttr
	 * @param bool $forPrivateKey
	 * @param int $index
	 * @param ?string $name
	 * @param ?string $value
	 * @param ?string $encoding
	 * @return bool
	 */
	function SetSafeBagAttr($forPrivateKey,$index,$name,$value,$encoding) {
		return CkPfx_SetSafeBagAttr($this->_cPtr,$forPrivateKey,$index,$name,$value,$encoding);
	}

	/**
	 * Serializes the current PFX contents as PKCS#12 data and writes the bytes to ARG2, using ARG1 as the output password.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#ToBd
	 * @param ?string $password
	 * @param CkBinData $bd
	 * @return bool
	 */
	function ToBd($password,$bd) {
		return CkPfx_ToBd($this->_cPtr,$password,$bd);
	}

	/**
	 * Serializes the current PFX contents to PKCS#12 bytes in memory, using ARG1 as the output password.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#ToBinary
	 * @param ?string $password
	 * @param CkByteData $outBytes
	 * @return bool
	 */
	function ToBinary($password,$outBytes) {
		return CkPfx_ToBinary($this->_cPtr,$password,$outBytes);
	}

	/**
	 * Serializes the current PFX contents using ARG1 as the output password, then returns the PKCS#12 bytes encoded as text using ARG2. Common choices for ARG2 are base64 and hex.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#ToEncodedString
	 * @param ?string $password
	 * @param ?string $encoding
	 * @return ?string
	 */
	function toEncodedString($password,$encoding) {
		return CkPfx_toEncodedString($this->_cPtr,$password,$encoding);
	}

	/**
	 * Serializes the current PFX contents and writes the resulting PKCS#12 data to ARG2, using ARG1 as the output password.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#ToFile
	 * @param ?string $password
	 * @param ?string $path
	 * @return bool
	 */
	function ToFile($password,$path) {
		return CkPfx_ToFile($this->_cPtr,$password,$path);
	}

	/**
	 * Deprecated. Use ToJksObj instead.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#ToJavaKeyStore
	 * @param ?string $alias
	 * @param ?string $password
	 * @return ?CkJavaKeyStore
	 * @deprecated
	 */
	function ToJavaKeyStore($alias,$password) {
		return chilkat::_obj(CkPfx_ToJavaKeyStore($this->_cPtr,$alias,$password),'CkJavaKeyStore');
	}

	/**
	 * Populates ARG3 with a Java KeyStore (JKS) representation of this PFX. One private-key entry is created for each private key, and certificates in the PFX are used to construct the corresponding certificate chains. ARG2 protects the generated private-key entries.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#ToJksObj
	 * @param ?string $alias
	 * @param ?string $password
	 * @param CkJavaKeyStore $jksObj
	 * @return bool
	 */
	function ToJksObj($alias,$password,$jksObj) {
		return CkPfx_ToJksObj($this->_cPtr,$alias,$password,$jksObj);
	}

	/**
	 * Exports all private keys and certificates currently held by this object as PEM-formatted text. Certificates are written as standard BEGIN CERTIFICATE blocks.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#ToPem
	 * @return ?string
	 */
	function toPem() {
		return CkPfx_toPem($this->_cPtr);
	}

	/**
	 * Exports selected PFX contents as PEM-formatted text. Certificates are written as standard BEGIN CERTIFICATE blocks. Private keys are always written in PKCS #8 form: BEGIN PRIVATE KEY when unencrypted, or BEGIN ENCRYPTED PRIVATE KEY when encrypted. Traditional PKCS #1 RSA, SEC 1 EC, DSA, and legacy OpenSSL encrypted-key PEM formats are not produced.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#ToPemEx
	 * @param bool $extendedAttrs
	 * @param bool $noKeys
	 * @param bool $noCerts
	 * @param bool $noCaCerts
	 * @param ?string $encryptAlg
	 * @param ?string $password
	 * @return ?string
	 */
	function toPemEx($extendedAttrs,$noKeys,$noCerts,$noCaCerts,$encryptAlg,$password) {
		return CkPfx_toPemEx($this->_cPtr,$extendedAttrs,$noKeys,$noCerts,$noCaCerts,$encryptAlg,$password);
	}

	/**
	 * Adds the certificates currently contained in ARG1 to the set of certificate sources available for later chain-building operations, such as AddCert.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPfxRef.html#UseCertVault
	 * @param CkXmlCertVault $vault
	 * @return bool
	 */
	function UseCertVault($vault) {
		return CkPfx_UseCertVault($this->_cPtr,$vault);
	}
}
